import React, { useContext, useState } from "react";
import ProductContext from "./store2/product-context";

const AddProduct = () => {
  const { openProduct, selectedItem, addItem } = useContext(ProductContext);
  const [quantity, setQuantity] = useState(1);

  const handleQuantityChange = (event) => {
    setQuantity(parseInt(event.target.value));
  };

  const addToCart = (size, quantity) => {
    const item = {
      id: selectedItem.id,
      name: `${selectedItem.name} (${size} - ${quantity})`,
      price: selectedItem.price,
      size: size,
      quantity: quantity,
    };
    addItem(item);
  };

  return (
    <div>
      {openProduct && selectedItem && (
        <div>
          <h2>{selectedItem.name}</h2>
          <p>Description: {selectedItem.description}</p>
          <p>Price: Rs {selectedItem.price}</p>
          <input
            type="number"
            value={quantity}
            onChange={handleQuantityChange}
          />
          {selectedItem.large > 0 && (
            <button onClick={() => addToCart("Large", quantity)}>
              Buy Large ({selectedItem.large} - {quantity})
            </button>
          )}
          {selectedItem.medium > 0 && (
            <button onClick={() => addToCart("Medium", quantity)}>
              Buy Medium ({selectedItem.medium} - {quantity})
            </button>
          )}
          {selectedItem.small > 0 && (
            <button onClick={() => addToCart("Small", quantity)}>
              Buy Small ({selectedItem.small} - {quantity})
            </button>
          )}
        </div>
      )}
    </div>
  );
};

export default AddProduct;
